# 2. Setup: writes the training code to /kaggle/working/train_code and finds the inputs.
#    Generated by scripts/train/make_train_cells.py from the tested repo code.
# v2. Inputs to attach: the competition (wheelhouse), the model google/gemma-4 -> gemma-4-12b-it-qat-w4a16-ct, the
# stage B v2 output (folder stage_b_v2_out), and if available: the PRIVATE dataset with gemma_val_samples.pt (Gemma's
# own pilot runs, validation only) and the 'finetuning' notebook output (the v1 adapter, scored for comparison).
import glob, json, os, subprocess, sys, time
from pathlib import Path

WORKING_DIR = Path('/kaggle/working')
CODE = WORKING_DIR / 'train_code'
CODE.mkdir(parents=True, exist_ok=True)
for name, text in {'int4_lora.py': '"""LoRA training on top of the competition\'s 4-bit checkpoint, without ever holding the 16-bit model in memory.\n\nWhy not plain transformers + PEFT: transformers loads a compressed-tensors checkpoint packed, but decompresses the\nWHOLE model to bf16 on the first forward pass (ModelCompressor.add_decompress_hook). For the 31B that is ~62 GB,\nmore than Kaggle\'s GPUs hold. Standard QLoRA (bitsandbytes NF4) would fit, but trains against a different 4-bit\nrounding than the int4 weights vLLM serves.\n\nHere every quantized Linear becomes an Int4LoRALinear: it keeps the packed int4 weights + bf16 group scales exactly as\nstored in the checkpoint (the same numbers vLLM serves), unpacks one layer\'s weight only while that layer runs, and\nadds a trainable LoRA branch. The saved adapter is a standard PEFT adapter (same file layout as the sample\nmain_lora that vLLM loaded on the scorer).\n"""\nimport json\nimport math\nfrom pathlib import Path\n\nimport torch\nimport torch.nn.functional as F\nfrom torch.utils.checkpoint import checkpoint\n\nDEFAULT_TARGETS = ("q_proj", "k_proj", "v_proj", "o_proj", "gate_proj", "up_proj", "down_proj")\n\n\ndef dequantize_int4(packed, scale, shape, args):\n    """The checkpoint\'s weight in bf16, computed with compressed-tensors\' own unpack/dequantize code."""\n    from compressed_tensors.compressors.pack_quantized.helpers import unpack_from_int32\n    from compressed_tensors.quantization.lifecycle.forward import dequantize\n    q = unpack_from_int32(packed, args.num_bits, torch.Size(shape))\n    return dequantize(x_q=q, scale=scale, args=args, dtype=scale.dtype)\n\n\nclass _Int4Matmul(torch.autograd.Function):\n    """y = x @ W.T with W rebuilt from int4 in forward and again in backward, so W is never kept between them."""\n\n    @staticmethod\n    def forward(ctx, x, packed, scale, shape, args):\n        w = dequantize_int4(packed, scale, shape, args)\n        ctx.save_for_backward(packed, scale)\n        ctx.shape, ctx.args = shape, args\n        return F.linear(x, w.to(x.dtype))  # same kernel as nn.Linear\n\n    @staticmethod\n    def backward(ctx, grad_y):\n        packed, scale = ctx.saved_tensors\n        w = dequantize_int4(packed, scale, ctx.shape, ctx.args)\n        return grad_y @ w.to(grad_y.dtype), None, None, None, None\n\n\nclass Int4LoRALinear(torch.nn.Module):\n    def __init__(self, linear, r=0, alpha=0, dropout=0.0):\n        super().__init__()\n        self.args = linear.quantization_scheme.weights\n        self.shape = tuple(int(s) for s in linear.weight_shape.tolist())\n        self.out_features, self.in_features = self.shape\n        self.register_buffer("weight_packed", linear.weight_packed.data, persistent=False)\n        self.register_buffer("weight_scale", linear.weight_scale.data.detach(), persistent=False)\n        self.r = r\n        if r:\n            dev, dt = self.weight_scale.device, torch.float32\n            self.lora_A = torch.nn.Parameter(torch.empty(r, self.in_features, device=dev, dtype=dt))\n            self.lora_B = torch.nn.Parameter(torch.zeros(self.out_features, r, device=dev, dtype=dt))\n            torch.nn.init.kaiming_uniform_(self.lora_A, a=math.sqrt(5))  # PEFT\'s default init\n            self.scaling = alpha / r\n            self.dropout = torch.nn.Dropout(dropout) if dropout else torch.nn.Identity()\n\n    def forward(self, x):\n        y = _Int4Matmul.apply(x, self.weight_packed, self.weight_scale, self.shape, self.args)\n        if self.r:  # fp32 master weights, bf16 math (as PEFT does with a bf16 model): no fp32 copy of activations\n            h = self.dropout(x)\n            y = y + (h @ self.lora_A.to(h.dtype).t()) @ self.lora_B.to(h.dtype).t() * self.scaling\n        return y\n\n    def extra_repr(self):\n        return f"in={self.in_features}, out={self.out_features}, int4 group={self.args.group_size}, r={self.r}"\n\n\ndef load_int4_model(path, device_map="auto", max_memory=None, attn_implementation="sdpa", dtype=torch.bfloat16):\n    """Load the checkpoint packed (4-bit in memory) with the class its config names."""\n    import transformers\n    from transformers import AutoConfig\n    cfg = AutoConfig.from_pretrained(path)\n    cls = getattr(transformers, cfg.architectures[0])\n    model = cls.from_pretrained(path, dtype=dtype, device_map=device_map, max_memory=max_memory,\n                                attn_implementation=attn_implementation)\n    if hasattr(model, "ct_decompress_hook"):  # never decompress the whole model\n        model.ct_decompress_hook.remove()\n        del model.ct_decompress_hook\n    return model\n\n\ndef add_lora(model, r=16, alpha=32, dropout=0.0, targets=DEFAULT_TARGETS, layers=None):\n    """Replace every packed Linear by Int4LoRALinear; the ones named in `targets` (in text layers `layers`, default\n    all) get a LoRA branch. Freezes everything else. Returns the names of the LoRA modules."""\n    for p in model.parameters():\n        p.requires_grad_(False)\n    swapped, lora = 0, []\n    for name, mod in list(model.named_modules()):\n        if not hasattr(mod, "weight_packed"):\n            continue\n        layer = _layer_index(name)\n        use = name.rsplit(".", 1)[-1] in targets and "language_model" in name and (layers is None or layer in layers)\n        parent_name, child = name.rsplit(".", 1)\n        setattr(model.get_submodule(parent_name), child,\n                Int4LoRALinear(mod, r=r if use else 0, alpha=alpha, dropout=dropout))\n        swapped += 1\n        if use:\n            lora.append(name)\n    assert swapped, "no packed (int4) Linear found: is this the compressed-tensors checkpoint?"\n    left = [n for n, m in model.named_modules() if hasattr(m, "weight_packed") and not isinstance(m, Int4LoRALinear)]\n    assert not left, f"packed layers not converted: {left[:3]}"\n    model._lora_cfg = dict(r=r, alpha=alpha, dropout=dropout, targets=sorted({n.rsplit(\'.\', 1)[-1] for n in lora}),\n                           layers=sorted({_layer_index(n) for n in lora}))\n    return lora\n\n\ndef _layer_index(name):\n    parts = name.split(".")\n    return int(parts[parts.index("layers") + 1]) if "layers" in parts else None\n\n\ndef text_hidden_states(model, input_ids):\n    """Final hidden states of the text decoder (before the tied output projection)."""\n    return model.model(input_ids=input_ids, use_cache=False, return_dict=True).last_hidden_state\n\n\ndef masked_lm_loss(model, hidden, labels, chunk=256):\n    """Mean next-token cross-entropy over positions whose label is not -100, with Gemma\'s final logit softcapping.\n\n    Logits (262k vocab) are computed only for labelled positions, `chunk` positions at a time, and recomputed in\n    backward (checkpoint), so a 32k-token sample never materializes a 32k x 262k logits tensor."""\n    w = model.get_output_embeddings().weight\n    cap = model.config.get_text_config().final_logit_softcapping\n    h = hidden[:, :-1].reshape(-1, hidden.shape[-1])\n    y = labels[:, 1:].reshape(-1).to(h.device)\n    keep = (y != -100).nonzero(as_tuple=True)[0]\n    if keep.numel() == 0:\n        return hidden.sum() * 0.0, 0\n\n    def chunk_loss(hc, yc):  # on the output matrix\'s GPU: moves a few MB of hidden states, not the 262k x d matrix\n        logits = (hc.to(w.device) @ w.t()).float()\n        if cap:\n            logits = torch.tanh(logits / cap) * cap\n        return F.cross_entropy(logits, yc.to(w.device), reduction="sum")\n\n    total = 0.0\n    for i in range(0, keep.numel(), chunk):\n        idx = keep[i:i + chunk]\n        total = total + checkpoint(chunk_loss, h[idx], y[idx], use_reentrant=False)\n    return total / keep.numel(), int(keep.numel())\n\n\ndef lora_state_dict(model):\n    """PEFT key names: base_model.model.<module path>.lora_A.weight / lora_B.weight (bf16)."""\n    sd = {}\n    for name, mod in model.named_modules():\n        if isinstance(mod, Int4LoRALinear) and mod.r:\n            sd[f"base_model.model.{name}.lora_A.weight"] = mod.lora_A.detach().to(torch.bfloat16).cpu().contiguous()\n            sd[f"base_model.model.{name}.lora_B.weight"] = mod.lora_B.detach().to(torch.bfloat16).cpu().contiguous()\n    return sd\n\n\ndef save_adapter(model, out_dir, base_model_name):\n    from safetensors.torch import save_file\n    out = Path(out_dir)\n    out.mkdir(parents=True, exist_ok=True)\n    c = model._lora_cfg\n    save_file(lora_state_dict(model), str(out / "adapter_model.safetensors"))\n    n_layers = model.config.get_text_config().num_hidden_layers\n    config = {\n        "alpha_pattern": {}, "auto_mapping": None, "base_model_name_or_path": base_model_name, "bias": "none",\n        "fan_in_fan_out": False, "inference_mode": True, "init_lora_weights": True, "layer_replication": None,\n        "layers_pattern": None, "layers_to_transform": None if c["layers"] == list(range(n_layers)) else c["layers"],\n        "loftq_config": {}, "lora_alpha": c["alpha"], "lora_dropout": c["dropout"], "megatron_config": None,\n        "megatron_core": "megatron.core", "modules_to_save": None, "peft_type": "LORA", "r": c["r"],\n        "rank_pattern": {}, "revision": None, "target_modules": c["targets"], "task_type": "CAUSAL_LM",\n        "use_dora": False, "use_rslora": False,\n    }\n    (out / "adapter_config.json").write_text(json.dumps(config, indent=2))\n    return out\n', 'build_samples.py': '"""Training samples from stage B\'s request logs: one token sequence per segment of an episode, loss only on what the\nmodel wrote.\n\n    python build_samples.py --stage-b <stage_b_out dir> [...] --tokenizer-dir <model dir> --out samples.pt\n\nAn episode\'s model calls form segments: inside a segment every prompt is exactly the previous prompt + the previous\nreply + the tool output (checked character for character), so the LAST call\'s prompt + its reply contains every\nreply of the segment. A compaction starts a new segment (the prompt then begins with the summary). Each segment\nbecomes one sequence; its labels are the token positions of the model\'s replies: thinking, tool calls and the stop\ntoken it emits (<|tool_response> after a tool call, <turn|> after the final message). Prompt, tool outputs and the\ncompaction summary are context only. ADK\'s summary calls themselves are not trained on.\n\nOnly attempts whose status.jsonl row says ok are used (crash-safe stage B: unfinished attempts are ignored).\n"""\nimport argparse\nimport json\nimport sys\nfrom collections import Counter, defaultdict\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom render_traces import load_template, render, request_to_template_inputs  # noqa: E402\n\n\ndef reply_message(rec):\n    """The model\'s reply as an assistant message, prepared the way vLLM prepares history (arguments as dicts)."""\n    m = rec["reply"]["message"]\n    out = {"role": "assistant"}\n    if m.get("content"):\n        out["content"] = m["content"]\n    if m.get("tool_calls"):\n        out["tool_calls"] = [dict(c, function=dict(c["function"], arguments=json.loads(c["function"]["arguments"] or "{}")\n                                                   if isinstance(c["function"]["arguments"], str)\n                                                   else c["function"]["arguments"]))\n                             for c in m["tool_calls"]]\n    thought = m.get("reasoning_content") or m.get("reasoning")\n    if thought:\n        out["reasoning_content"] = out["reasoning"] = thought\n    return out\n\n\ndef episode_segments(records, tmpl, bos, problems):\n    """[(text, [(start, end) char spans of replies])] for one episode\'s records (time order)."""\n    segs, cur, summary_seen = [], None, False\n    for rec in records:\n        if not rec["request"].get("tools"):  # ADK compaction summary\n            summary_seen = True\n            continue\n        msgs, tools, think = request_to_template_inputs(rec)\n        prompt = render(tmpl, bos, msgs, tools, enable_thinking=think)\n        full = render(tmpl, bos, msgs + [reply_message(rec)], tools, enable_thinking=think, add_generation_prompt=False)\n        if not full.startswith(prompt):\n            problems["reply does not extend the prompt"] += 1\n            return None\n        end = len(full) - 1 if full.endswith("<turn|>\\n") else len(full)  # the newline is template layout\n        if cur is not None and prompt.startswith(cur["text"]):\n            cur["text"], cur["spans"] = full, cur["spans"] + [(len(prompt), end)]\n        else:\n            if cur is not None and not summary_seen:\n                problems["new segment without a compaction"] += 1\n                return None\n            cur = {"text": full, "spans": [(len(prompt), end)]}\n            segs.append(cur)\n        summary_seen = False\n    return [(s["text"], s["spans"]) for s in segs]\n\n\ndef tokenize_segment(tok, text, spans):\n    enc = tok.encode(text, add_special_tokens=False)\n    ids = enc.ids\n    starts = {a for a, _ in spans}\n    lab = []\n    for i, (a, b) in enumerate(enc.offsets):\n        inside = any(x <= a and b <= y for x, y in spans)\n        lab.append(inside)\n    # every reply must start exactly on a token boundary (they start with a special token)\n    token_starts = {a for a, _ in enc.offsets}\n    assert starts <= token_starts, "a reply does not start on a token boundary"\n    return ids, lab\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--stage-b", nargs="+", required=True, help="stage_b_out folder(s): requests_*.jsonl + status.jsonl")\n    ap.add_argument("--tokenizer-dir", required=True)\n    ap.add_argument("--out", required=True)\n    ap.add_argument("--max-len", type=int, default=32768)\n    a = ap.parse_args()\n    import torch\n    from tokenizers import Tokenizer\n    tmpl, bos = load_template(a.tokenizer_dir)\n    tok = Tokenizer.from_file(str(Path(a.tokenizer_dir) / "tokenizer.json"))\n\n    ok = {}\n    for d in a.stage_b:\n        for line in (Path(d) / "status.jsonl").read_text().splitlines():\n            r = json.loads(line)\n            if r["status"] == "ok":\n                ok[(r["id"], r["attempt"])] = r\n    print(f"stage B episodes ok: {len(ok)}", flush=True)\n    recs = defaultdict(list)\n    for d in a.stage_b:\n        for f in sorted(Path(d).glob("requests_*.jsonl")):\n            with open(f) as fh:\n                for line in fh:\n                    r = json.loads(line)\n                    if (r.get("episode_id"), r.get("attempt")) in ok:\n                        recs[(r["episode_id"], r["attempt"])].append(r)\n    problems = Counter()\n    samples = []\n    for n, (key, rs) in enumerate(sorted(recs.items())):\n        rs.sort(key=lambda r: r["t"])\n        meta = ok[key]\n        try:  # one odd episode is skipped and counted, never stops the build\n            segs = episode_segments(rs, tmpl, bos, problems)\n            tokenized = None if segs is None else [tokenize_segment(tok, text, spans) for text, spans in segs]\n        except Exception as e:  # noqa: BLE001\n            problems[f"error {type(e).__name__}"] += 1\n            segs = None\n            print(f"  skip {key[0]}: {e!r}"[:300], flush=True)\n        if segs is None:\n            continue\n        for k, ((text, spans), (ids, lab)) in enumerate(zip(segs, tokenized)):\n            if len(ids) > a.max_len:\n                problems["segment longer than max-len"] += 1\n                continue\n            samples.append({"episode_id": key[0], "split": meta["split"], "category": meta.get("category"),\n                            "teacher": meta.get("teacher"), "segment": k, "n_segments": len(segs),\n                            "replies": len(spans), "input_ids": torch.tensor(ids, dtype=torch.int32),\n                            "labels_mask": torch.tensor(lab, dtype=torch.bool)})\n        if (n + 1) % 50 == 0 or n + 1 == len(recs):\n            print(f"  {n + 1}/{len(recs)} episodes -> {len(samples)} segments", flush=True)\n    missing = len(ok) - len(recs)\n    torch.save(samples, a.out)\n    print(f"\\nwrote {len(samples)} segments -> {a.out}; episodes without records {missing}; problems {dict(problems)}")\n    for split in ("train", "val"):\n        s = [x for x in samples if x["split"] == split]\n        if not s:\n            continue\n        lens = sorted(len(x["input_ids"]) for x in s)\n        labs = [int(x["labels_mask"].sum()) for x in s]\n        print(f"{split}: {len({x[\'episode_id\'] for x in s})} episodes, {len(s)} segments, "\n              f"{sum(lens) / 1e6:.2f}M tokens (trained on {sum(labs) / 1e6:.2f}M = {100 * sum(labs) / sum(lens):.1f}%), "\n              f"length median {lens[len(lens) // 2]} p90 {lens[int(len(lens) * .9)]} max {lens[-1]}, "\n              f"segments per episode {dict(Counter(x[\'n_segments\'] for x in s if x[\'segment\'] == 0))}")\n\n\nif __name__ == "__main__":\n    main()\n', 'train_sft.py': '"""LoRA SFT of the competition\'s 4-bit Gemma on stage B samples (build_samples.py), data-parallel over GPUs.\n\n    torchrun --nproc_per_node <ranks> train_sft.py --model <ckpt> --samples samples.pt --out <dir> [options]\n    python train_sft.py --model <ckpt> --samples samples.pt --out <dir> --probe   # memory/speed test, one rank\n\nEach rank holds its own copy of the model (int4 weights + LoRA, scripts/train/int4_lora.py) on --gpus-per-rank GPUs\n(1 if the 12B fits on one L4 at our longest segment; else 2, split by layers). One optimizer step = ranks x --accum\nsegments; the loss is the mean over every trained token of the step (all ranks), so long and short segments weigh\nby their tokens. LoRA gradients are summed across ranks before clipping, so all copies stay identical.\n\nVerbose by design (user): one line per step (loss, running average, lr, grad norm, tokens/s, GPU memory, ETA),\nvalidation loss before training, at every --eval-every and at the end; adapters saved at those points (PEFT format,\nsame as the scorer-tested one) plus a resumable trainer state. Re-running resumes from the last saved step.\n"""\nimport argparse\nimport datetime\nimport json\nimport math\nimport os\nimport random\nimport sys\nimport time\nfrom pathlib import Path\n\nimport torch\nimport torch.distributed as dist\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\nfrom int4_lora import (Int4LoRALinear, add_lora, load_int4_model, masked_lm_loss, save_adapter,  # noqa: E402\n                       text_hidden_states)\n\n\ndef log(msg, rank=0, me=None):\n    if me is None or me == rank:\n        print(msg, flush=True)\n\n\ndef setup():\n    if "RANK" in os.environ:\n        backend = "nccl" if torch.cuda.is_available() else "gloo"\n        # a hang (copies waiting on different collectives) becomes an error after 40 min instead of burning quota;\n        # the notebook then resumes from the last checkpoint\n        dist.init_process_group(backend, timeout=datetime.timedelta(minutes=40))\n        return dist.get_rank(), dist.get_world_size()\n    return 0, 1\n\n\ndef all_sum(x, dev):\n    t = torch.tensor(x, dtype=torch.float64, device=dev)\n    if dist.is_initialized():\n        dist.all_reduce(t)\n    return t.item()\n\n\ndef from_rank0(x, dev):\n    """Every copy takes rank 0\'s value: decisions that change the loop must be identical on all copies."""\n    t = torch.tensor(x, dtype=torch.float64, device=dev)\n    if dist.is_initialized():\n        dist.broadcast(t, 0)\n    return t.item()\n\n\ndef all_max(x, dev):\n    t = torch.tensor(x, dtype=torch.float64, device=dev)\n    if dist.is_initialized():\n        dist.all_reduce(t, op=dist.ReduceOp.MAX)\n    return t.item()\n\n\ndef load_model(args, rank):\n    if torch.cuda.is_available():\n        gpus = list(range(rank * args.gpus_per_rank, (rank + 1) * args.gpus_per_rank))\n        if len(gpus) == 1:\n            device_map, max_memory = {"": gpus[0]}, None\n        else:\n            device_map = "balanced"\n            max_memory = {g: f"{int(torch.cuda.get_device_properties(g).total_memory / 2**30 * 0.45)}GiB" for g in gpus}\n    else:\n        gpus, device_map, max_memory = [], None, None\n    model = load_int4_model(args.model, device_map=device_map, max_memory=max_memory, attn_implementation=args.attn)\n    torch.manual_seed(args.seed)  # same LoRA init on every rank (also broadcast below)\n    add_lora(model, r=args.r, alpha=args.alpha, dropout=args.dropout)\n    model.gradient_checkpointing_enable(gradient_checkpointing_kwargs={"use_reentrant": False})\n    model.config.use_cache = False\n    model.train()\n    return model, gpus\n\n\ndef lora_params(model):\n    ps = []\n    for _, mod in model.named_modules():\n        if isinstance(mod, Int4LoRALinear) and mod.r:\n            ps += [mod.lora_A, mod.lora_B]\n    return ps\n\n\ndef load_adapter_weights(model, adapter_dir):\n    """Put a saved PEFT adapter\'s LoRA weights into our model (to score an earlier adapter, e.g. v1)."""\n    from safetensors.torch import load_file\n    sd = load_file(str(Path(adapter_dir) / "adapter_model.safetensors"))\n    n = 0\n    for name, mod in model.named_modules():\n        if isinstance(mod, Int4LoRALinear) and mod.r:\n            mod.lora_A.data.copy_(sd[f"base_model.model.{name}.lora_A.weight"].to(mod.lora_A.device, torch.float32))\n            mod.lora_B.data.copy_(sd[f"base_model.model.{name}.lora_B.weight"].to(mod.lora_B.device, torch.float32))\n            n += 1\n    return n\n\n\ndef first_device(model):\n    return model.get_input_embeddings().weight.device\n\n\ndef segment_loss(model, sample, dev):\n    ids = sample["input_ids"].long().unsqueeze(0).to(dev)\n    labels = torch.where(sample["labels_mask"].unsqueeze(0).to(dev), ids, torch.full_like(ids, -100))\n    hidden = text_hidden_states(model, ids)\n    mean, n = masked_lm_loss(model, hidden, labels)\n    return mean * n, n\n\n\ndef gpu_mem_gib(gpus):\n    return max((torch.cuda.max_memory_allocated(g) / 2**30 for g in gpus), default=0.0)\n\n\ndef batches(items, world, accum, seed, epoch):\n    """Global batches of world*accum segments; inside a batch, lengths are dealt so every rank gets a similar load."""\n    order = list(range(len(items)))\n    random.Random(seed * 1000 + epoch).shuffle(order)\n    size = world * accum\n    out = []\n    for i in range(0, len(order), size):\n        b = sorted(order[i:i + size], key=lambda j: -len(items[j]["input_ids"]))\n        out.append([b[r::world] for r in range(world)])\n    return out\n\n\ndef evaluate(model, val, rank, world, dev):\n    model.eval()\n    mine = sorted(range(len(val)), key=lambda j: -len(val[j]["input_ids"]))[rank::world]\n    tot = n = 0.0\n    with torch.no_grad():\n        for j in mine:\n            s, k = segment_loss(model, val[j], first_device(model))\n            tot, n = tot + s.item(), n + k\n    model.train()\n    tot, n = all_sum(tot, dev), all_sum(n, dev)\n    return tot / max(n, 1), int(n)\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--model", required=True)\n    ap.add_argument("--samples", required=True)\n    ap.add_argument("--out", required=True)\n    ap.add_argument("--base-name", default="gemma-4-12b-it-qat-w4a16-ct")\n    ap.add_argument("--gpus-per-rank", type=int, default=1)\n    ap.add_argument("--epochs", type=float, default=1.0)\n    ap.add_argument("--accum", type=int, default=2, help="segments per rank per optimizer step")\n    ap.add_argument("--lr", type=float, default=2e-4)\n    ap.add_argument("--min-lr-ratio", type=float, default=0.1)\n    ap.add_argument("--warmup", type=int, default=8)\n    ap.add_argument("--clip", type=float, default=1.0)\n    ap.add_argument("--r", type=int, default=16)\n    ap.add_argument("--alpha", type=int, default=32)\n    ap.add_argument("--dropout", type=float, default=0.0)\n    ap.add_argument("--seed", type=int, default=20261018)\n    ap.add_argument("--attn", default="sdpa")\n    ap.add_argument("--eval-every", type=int, default=0, help="steps between validation runs (0: --evals per run)")\n    ap.add_argument("--evals", type=int, default=4, help="mid-run validations per run (when --eval-every is 0)")\n    ap.add_argument("--early-stop-patience", type=int, default=0, help="stop when the mid-run validation loss has not "\n                    "improved by --min-delta for this many validations in a row (0: off)")\n    ap.add_argument("--min-delta", type=float, default=0.005)\n    ap.add_argument("--monitor", default="val", help="validation set the mid-run checks, the plateau stop and the best "\n                    "checkpoint use: \'val\' (teacher, 24-segment subset) or a split of --extra-val, e.g. val_gemma_ok "\n                    "(Gemma\'s own resolved runs, scored in full)")\n    ap.add_argument("--val-max", type=int, default=24, help="validation segments used mid-run (0: all); start and "\n                    "final always use all")\n    ap.add_argument("--save-every", type=int, default=10, help="steps between resumable checkpoints")\n    ap.add_argument("--max-hours", type=float, default=0, help="stop training in time (schedule re-planned to fit)")\n    ap.add_argument("--extra-val", nargs="*", default=[], help="more samples files (e.g. Gemma\'s own runs): each split "\n                    "in them is scored separately at the start and at the end")\n    ap.add_argument("--score-adapter", default=None, help="adapter folder to score on every validation set before "\n                    "training (e.g. v1), then training starts from a fresh LoRA")\n    ap.add_argument("--probe", action="store_true", help="one rank: fwd+bwd on the longest train segment, report memory")\n    ap.add_argument("--max-steps", type=int, default=0, help="tests: stop after this many steps")\n    args = ap.parse_args()\n    t_start = time.time()\n    rank, world = setup()\n    out = Path(args.out)\n    if rank == 0:\n        out.mkdir(parents=True, exist_ok=True)\n    samples = torch.load(args.samples)\n    train = [s for s in samples if s["split"] == "train"]\n    val = [s for s in samples if s["split"] == "val"]\n    extra = {}\n    for f in args.extra_val:\n        for s in torch.load(f):\n            extra.setdefault(s["split"], []).append(s)\n    log(f"ranks {world} x {args.gpus_per_rank} GPU(s) | train {len(train)} segments "\n        f"{sum(len(s[\'input_ids\']) for s in train) / 1e6:.2f}M tokens ({sum(int(s[\'labels_mask\'].sum()) for s in train) / 1e6:.2f}M trained) "\n        f"| val {len(val)} segments", 0, rank)\n\n    t0 = time.time()\n    model, gpus = load_model(args, rank)\n    dev = first_device(model)\n    params = lora_params(model)\n    log(f"model loaded in {time.time() - t0:.0f}s on GPUs {gpus or \'cpu\'}; LoRA r={args.r} alpha={args.alpha}: "\n        f"{sum(p.numel() for p in params) / 1e6:.1f}M trainable params in {len(params)} tensors", 0, rank)\n\n    if args.probe:\n        s = max(train, key=lambda x: len(x["input_ids"]))\n        if torch.cuda.is_available():\n            for g in gpus:\n                torch.cuda.reset_peak_memory_stats(g)\n        t0 = time.time()\n        loss_sum, n = segment_loss(model, s, dev)\n        (loss_sum / n).backward()\n        if torch.cuda.is_available():\n            torch.cuda.synchronize()\n        secs = time.time() - t0\n        res = {"ok": True, "tokens": len(s["input_ids"]), "seconds": round(secs, 1),\n               "tokens_per_s": round(len(s["input_ids"]) / secs, 1), "loss": round((loss_sum / n).item(), 4),\n               "peak_gib": round(gpu_mem_gib(gpus), 2), "gpus_per_rank": args.gpus_per_rank}\n        print("PROBE", json.dumps(res), flush=True)\n        (out / f"probe_g{args.gpus_per_rank}.json").write_text(json.dumps(res))\n        return\n\n    if dist.is_initialized():  # identical start on every rank\n        for p in params:\n            t = p.data.to(dev)\n            dist.broadcast(t, 0)\n            p.data.copy_(t.to(p.device))\n    opt = torch.optim.AdamW(params, lr=args.lr, betas=(0.9, 0.999), weight_decay=0.0)\n    per_epoch = math.ceil(len(train) / (world * args.accum))\n    plan = {"total": max(1, int(per_epoch * args.epochs))}\n\n    def lr_at(step):  # linear warmup, cosine to min_lr_ratio over the (possibly re-planned) total\n        if step < args.warmup:\n            return args.lr * (step + 1) / args.warmup\n        prog = min(1.0, (step - args.warmup) / max(1, plan["total"] - args.warmup))\n        return args.lr * (args.min_lr_ratio + (1 - args.min_lr_ratio) * 0.5 * (1 + math.cos(math.pi * prog)))\n\n    step, history = 0, []\n    state_path = out / "last" / "trainer_state.pt"\n    if state_path.exists():  # resume\n        st = torch.load(state_path, map_location="cpu")\n        for p, v in zip(params, st["lora"]):\n            p.data.copy_(v.to(p.device))\n        opt.load_state_dict(st["opt"])\n        step, plan, history = st["step"], st["plan"], st["history"]\n        log(f"RESUMED at step {step}/{plan[\'total\']}", 0, rank)\n    plan.setdefault("best", None)\n    plan.setdefault("bad", 0)\n    eval_every = args.eval_every or max(1, plan["total"] // (args.evals + 1))\n    log(f"plan: {plan[\'total\']} optimizer steps ({per_epoch}/epoch x {args.epochs} epochs), "\n        f"{world * args.accum} segments per step, lr {args.lr} warmup {args.warmup} cosine->{args.min_lr_ratio}, "\n        f"validation every {eval_every} steps", 0, rank)\n\n    def save_state():  # resumable checkpoint (rank 0 only; no collectives)\n        if rank != 0:\n            return\n        save_adapter(model, out / "last", args.base_name)\n        torch.save({"lora": [p.detach().cpu() for p in params], "opt": opt.state_dict(), "step": step, "plan": plan,\n                    "history": history}, str(state_path) + ".tmp")\n        os.replace(str(state_path) + ".tmp", state_path)  # never a half-written checkpoint\n        log(f"  checkpoint at step {step}", 0, rank)\n\n    def save(tag):\n        if rank != 0:\n            return\n        save_adapter(model, out / tag, args.base_name)\n        save_adapter(model, out / "last", args.base_name)\n        torch.save({"lora": [p.detach().cpu() for p in params], "opt": opt.state_dict(), "step": step, "plan": plan,\n                    "history": history}, str(state_path) + ".tmp")\n        os.replace(str(state_path) + ".tmp", state_path)  # never a half-written checkpoint\n        (out / "history.json").write_text(json.dumps(history, indent=1))\n        log(f"  saved adapter {out / tag}", 0, rank)\n\n    eval_secs = {}\n\n    def run_eval(tag):\n        t0 = time.time()\n        vs = sorted(val, key=lambda x: len(x["input_ids"]))\n        if args.val_max and tag not in ("start", "final"):\n            vs = vs[::max(1, len(vs) // args.val_max)][:args.val_max]\n        loss, n = evaluate(model, vs, rank, world, dev)\n        history.append({"type": "val", "tag": tag, "step": step, "val_loss": round(loss, 4), "val_tokens": n,\n                        "segments": len(vs), "seconds": round(time.time() - t0)})\n        eval_secs[tag] = (time.time() - t0, len(vs))\n        log(f"VAL [{tag}] step {step}: loss {loss:.4f} over {n} trained tokens in {len(vs)} segments "\n            f"({time.time() - t0:.0f}s)", 0, rank)\n        return loss\n\n    def eval_set(split, segs, tag):\n        t0 = time.time()\n        loss, n = evaluate(model, segs, rank, world, dev)\n        history.append({"type": "val", "set": split, "tag": tag, "step": step, "val_loss": round(loss, 4),\n                        "val_tokens": n, "segments": len(segs), "seconds": round(time.time() - t0)})\n        log(f"VAL [{tag}] {split}: loss {loss:.4f} over {n} trained tokens in {len(segs)} segments "\n            f"({time.time() - t0:.0f}s)", 0, rank)\n        return loss\n\n    def run_extra(tag):  # the extra validation sets (Gemma\'s resolved / failed runs), full each time\n        for split, segs in sorted(extra.items()):\n            eval_set(split, segs, tag)\n\n    monitor = args.monitor if (args.monitor == "val" or args.monitor in extra) else "val"\n    if monitor != args.monitor:\n        log(f"WARNING: --monitor {args.monitor} not among the validation sets; monitoring \'val\' instead", 0, rank)\n    log(f"mid-run checks, plateau stop and best checkpoint use: {monitor}", 0, rank)\n\n    if step == 0 and args.score_adapter:  # score an earlier adapter on the same sets, then start fresh\n        fresh = [p.detach().clone() for p in params]\n        k = load_adapter_weights(model, args.score_adapter)\n        log(f"scoring adapter {args.score_adapter} ({k} LoRA modules loaded)", 0, rank)\n        if val:\n            loss, n = evaluate(model, val, rank, world, dev)\n            history.append({"type": "val", "set": "val", "tag": "scored_adapter", "step": 0, "val_loss": round(loss, 4),\n                            "val_tokens": n, "segments": len(val)})\n            log(f"VAL [scored_adapter] val: loss {loss:.4f} over {n} trained tokens in {len(val)} segments", 0, rank)\n        run_extra("scored_adapter")\n        for p, v in zip(params, fresh):\n            p.data.copy_(v)\n    if step == 0 and val:\n        run_eval("start")\n    if step == 0:\n        run_extra("start")\n    all_batches = [b for e in range(math.ceil(args.epochs)) for b in batches(train, world, args.accum, args.seed, e)]\n    ema, t_train, steps_timed = None, time.time(), 0\n    while step < plan["total"] and step < len(all_batches):\n        if args.max_steps and step >= args.max_steps:\n            break\n        t0 = time.time()\n        mine = [train[j] for j in all_batches[step][rank]]\n        my_lab = sum(int(s["labels_mask"].sum()) for s in mine)\n        g_lab = all_sum(my_lab, dev)\n        for g in gpus:\n            torch.cuda.reset_peak_memory_stats(g)\n        tot = 0.0\n        for s in mine:\n            loss_sum, _ = segment_loss(model, s, dev)\n            (loss_sum / g_lab).backward()\n            tot += loss_sum.item()\n        flat = torch.cat([(p.grad if p.grad is not None else torch.zeros_like(p)).flatten().to(dev) for p in params])\n        if dist.is_initialized():\n            dist.all_reduce(flat)\n        gnorm = flat.norm().item()\n        if args.clip and gnorm > args.clip:\n            flat.mul_(args.clip / (gnorm + 1e-6))\n        i = 0\n        for p in params:\n            k = p.numel()\n            p.grad = flat[i:i + k].view_as(p).to(p.device)\n            i += k\n        lr = lr_at(step)\n        for gr in opt.param_groups:\n            gr["lr"] = lr\n        opt.step()\n        opt.zero_grad(set_to_none=True)\n        step += 1\n        loss = all_sum(tot, dev) / max(g_lab, 1)\n        toks = all_sum(sum(len(s["input_ids"]) for s in mine), dev)\n        mem = all_max(gpu_mem_gib(gpus), dev)\n        secs = time.time() - t0\n        ema = loss if ema is None else 0.9 * ema + 0.1 * loss\n        steps_timed += 1\n        avg_step = (time.time() - t_train) / steps_timed\n        if args.max_hours and steps_timed == 3:  # re-plan once the speed is known (rank 0 decides for everyone)\n            full = eval_secs.get("start", (0.0, max(len(val), 1)))\n            per_seg = full[0] / max(full[1], 1)\n            n_mid = min(args.val_max or len(val), len(val)) if monitor == "val" else len(extra[monitor])\n            evals = per_seg * (len(val) + args.evals * n_mid + sum(len(v) for v in extra.values())) + 120  # final+mid+extra\n            left = args.max_hours * 3600 - (time.time() - t_start) - evals\n            fit = int(from_rank0(step + max(0, int(left / avg_step)), dev))\n            if fit < plan["total"]:\n                log(f"TIME BUDGET: {plan[\'total\']} steps would take {plan[\'total\'] * avg_step / 3600:.1f}h; "\n                    f"re-planned to {fit} steps to finish within {args.max_hours}h", 0, rank)\n                plan["total"] = fit\n                eval_every = args.eval_every or max(1, fit // (args.evals + 1))\n        eta = (plan["total"] - step) * avg_step\n        history.append({"type": "train", "step": step, "loss": round(loss, 4), "ema": round(ema, 4), "lr": lr,\n                        "grad_norm": round(gnorm, 4), "tokens": int(toks), "trained_tokens": int(g_lab),\n                        "seconds": round(secs, 1), "mem_gib": round(mem, 2)})\n        log(f"step {step:4}/{plan[\'total\']} | loss {loss:.4f} (avg {ema:.4f}) | lr {lr:.2e} | grad {gnorm:.3f} | "\n            f"{int(toks):6} tok ({int(g_lab)} trained) {toks / secs:6.0f} tok/s | mem {mem:.1f} GiB | "\n            f"{secs:5.1f}s | ETA {eta / 60:5.1f} min", 0, rank)\n        if step % eval_every == 0 and step < plan["total"]:\n            stop = False\n            loss_v = None\n            if monitor != "val":  # the chosen validation set (e.g. Gemma\'s resolved runs), in full every time\n                loss_v = eval_set(monitor, extra[monitor], f"step{step}")\n            elif val:\n                loss_v = run_eval(f"step{step}")  # the same 24-segment subset every time: comparable across steps\n            if loss_v is not None:\n                if plan["best"] is None or loss_v < plan["best"] - args.min_delta:\n                    plan["best"], plan["bad"] = loss_v, 0\n                    save("best")\n                    log(f"  new best mid-run {monitor} loss {loss_v:.4f} -> saved as best", 0, rank)\n                else:\n                    plan["bad"] += 1\n                    log(f"  no improvement over best {plan[\'best\']:.4f} (by {args.min_delta}) for {plan[\'bad\']} "\n                        f"validation(s)", 0, rank)\n                    stop = bool(args.early_stop_patience) and plan["bad"] >= args.early_stop_patience\n            save(f"step_{step}")\n            if from_rank0(1.0 if stop else 0.0, dev) > 0.5:  # rank 0 decides for every copy\n                log(f"EARLY STOP at step {step}: validation loss plateaued ({plan[\'bad\']} validations without "\n                    f"improvement); final validation + save next", 0, rank)\n                break\n        elif step % args.save_every == 0:\n            save_state()\n    if val:\n        run_eval("final")\n    run_extra("final")\n    save("final")\n    if rank == 0:\n        vals = [h for h in history if h["type"] == "val"]\n        log("\\nVALIDATION LOSS: " + " | ".join(f"{h.get(\'set\', \'val\')}@{h[\'tag\']} {h[\'val_loss\']}" for h in vals), 0, rank)\n        log(f"done: {step} steps in {(time.time() - t_start) / 3600:.2f}h -> {out / \'final\'}", 0, rank)\n    if dist.is_initialized():\n        dist.destroy_process_group()\n\n\nif __name__ == "__main__":\n    main()\n', 'render_traces.py': '"""Rebuild the exact prompt vLLM saw at each model call of a harness trace, in Gemma 4\'s chat format.\n\nRun with the harness venv (exact competition versions):\n    data/venv_harness/bin/python scripts/render_traces.py data/results/<run>/results/<arm>/traces/trace_<task>.json\n\nIt rebuilds the OpenAI-style request the way the harness builds it (ADK LiteLlm conversion + adk_submission\'s\nreasoning patch + the real swegemma tool definitions), renders it with data/gemma4_tokenizer/chat_template.jinja,\ntokenizes it, and compares the token count with the prompt_tokens vLLM recorded for that step. Equal counts mean the\nrendering matches what the model was actually trained against at inference time; the training samples are built on\ntop of this.\n"""\nimport argparse\nimport json\nimport sys\nfrom pathlib import Path\n\nimport jinja2\nfrom tokenizers import Tokenizer\n\nROOT = Path(__file__).resolve().parents[1]\nTOK_DIR = ROOT / "data" / "gemma4_tokenizer"\nDEFAULT_TOOLS = ["run_command", "read_file", "edit_file", "write_file", "get_status", "submit_patch"]\n\n\ndef tool_params(names):\n    """OpenAI tool dicts for the harness tools, built by the same code path the harness uses."""\n    import adk_submission  # noqa: F401  (installs the schema / reasoning patches on ADK\'s LiteLlm module)\n    from google.adk.models import lite_llm\n    from google.adk.tools import FunctionTool\n    from swegemma.tools import create_tools\n\n    class _Ctx:  # the factories only close over ctx; nothing is called here\n        def __getattr__(self, name):\n            return None\n\n    funcs = create_tools(_Ctx())\n    return [lite_llm._function_declaration_to_tool_param(FunctionTool(funcs[n])._get_declaration()) for n in names]\n\n\ndef load_template(tok_dir=TOK_DIR):\n    tok_dir = Path(tok_dir)\n    env = jinja2.Environment(trim_blocks=True, lstrip_blocks=True, extensions=["jinja2.ext.loopcontrols"])\n    env.filters["tojson"] = lambda v, **k: json.dumps(v, **k)\n    tmpl = env.from_string((tok_dir / "chat_template.jinja").read_text())\n    cfg = json.loads((tok_dir / "tokenizer_config.json").read_text())\n    return tmpl, cfg.get("bos_token", "<bos>")\n\n\ndef render(tmpl, bos, messages, tools, enable_thinking=True, add_generation_prompt=True):\n    return tmpl.render(messages=messages, tools=tools, bos_token=bos, enable_thinking=enable_thinking,\n                       add_generation_prompt=add_generation_prompt)\n\n\ndef messages_until(trace, step_index, agent_name="swe_agent", agent_description=None, args_as="dict"):\n    """The OpenAI messages the harness sent for the model call made at trace step `step_index`.\n\n    ADK builds the system prompt as the agent instruction, then (identity processor) a blank line and\n    \'You are an agent. Your internal name is "<name>".\' plus the description if the agent has one."""\n    identity = f\'You are an agent. Your internal name is "{agent_name}".\'\n    if agent_description:\n        identity += f\' The description about you is "{agent_description}".\'\n    steps = trace["steps"]\n    msgs = []\n    pending_text = None  # a visible-text step: content of the next assistant message\n    for st in steps[:step_index]:\n        src = st.get("source")\n        etype = (st.get("extra") or {}).get("event_type")\n        if src == "system" and etype == "system_instruction":\n            msgs.append({"role": "system", "content": st["message"] + "\\n\\n" + identity})\n        elif src == "user" or (src == "system" and st.get("message") and etype not in (None, "usage")):\n            # the task prompt and harness nudges (continuation_nudge, ...) are user messages\n            msgs.append({"role": "user", "content": st["message"]})\n        elif src == "agent":\n            if etype == "text" and not st.get("tool_calls"):\n                pending_text = (pending_text + "\\n" if pending_text else "") + (st.get("message") or "")\n                continue\n            calls = []\n            for tc in st.get("tool_calls") or []:\n                args = tc.get("arguments") or {}\n                calls.append({"id": tc.get("tool_call_id", ""), "type": "function",\n                              "function": {"name": tc["function_name"],\n                                           "arguments": args if args_as == "dict" else json.dumps(args)}})\n            thought = (st.get("message") or None) if etype != "text" else None\n            content = pending_text if etype != "text" else st.get("message")\n            pending_text = None\n            msgs.append({"role": "assistant", "content": content, "tool_calls": calls or None,\n                         "reasoning_content": thought, "reasoning": thought})\n            obs = st.get("observation") or {}\n            if calls and isinstance(obs, dict) and "content" in obs:\n                msgs.append({"role": "tool", "tool_call_id": calls[0]["id"], "content": obs["content"]})\n    return msgs\n\n\ndef request_to_template_inputs(record):\n    """messages, tools and enable_thinking from a request recorded by scripts/request_logger.py, prepared the way\n    vLLM prepares them (tool-call arguments parsed from JSON strings into dicts)."""\n    req = record["request"]\n    msgs = []\n    for m in req["messages"]:\n        m = dict(m)\n        if m.get("tool_calls"):\n            calls = []\n            for c in m["tool_calls"]:\n                c = json.loads(json.dumps(c))\n                args = c["function"].get("arguments")\n                if isinstance(args, str):\n                    try:\n                        c["function"]["arguments"] = json.loads(args) if args.strip() else {}\n                    except json.JSONDecodeError:\n                        pass\n                calls.append(c)\n            m["tool_calls"] = calls\n        msgs.append(m)\n    # vLLM hands message text to the chat template as OpenAI content parts, not a plain string; for the SYSTEM turn\n    # Gemma\'s template then adds a space before <turn|> (one extra token, confirmed with vLLM\'s /tokenize: 27 vs 26)\n    msgs = [dict(m, content=[{"type": "text", "text": m["content"]}])\n            if m.get("role") == "system" and isinstance(m.get("content"), str) else m for m in msgs]\n    kw = req.get("kwargs") or {}\n    ctk = kw.get("chat_template_kwargs") or (kw.get("extra_body") or {}).get("chat_template_kwargs") or {}\n    return msgs, req.get("tools"), bool(ctk.get("enable_thinking"))\n\n\ndef check_requests(path, limit=None):\n    """Render every recorded request and compare with the prompt_tokens vLLM reported for it."""\n    import gzip\n    tmpl, bos = load_template()\n    tok = Tokenizer.from_file(str(TOK_DIR / "tokenizer.json"))\n    exact = off = 0\n    for n, line in enumerate(gzip.open(path, "rt") if str(path).endswith(".gz") else open(path)):\n        if limit and n >= limit:\n            break\n        rec = json.loads(line)\n        usage = (rec.get("reply") or {}).get("usage") if isinstance(rec.get("reply"), dict) else None\n        if not usage:\n            continue\n        msgs, tools, think = request_to_template_inputs(rec)\n        got = len(tok.encode(render(tmpl, bos, msgs, tools, enable_thinking=think), add_special_tokens=False).ids)\n        want = usage["prompt_tokens"]\n        exact, off = (exact + 1, off) if got == want else (exact, off + 1)\n        if got != want and off <= 10:\n            print(f"request {n}: vLLM {want} rendered {got} diff {got - want:+d}")\n    print(f"requests rendered exactly: {exact}, different: {off}")\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("trace", help="a harness trace (.json) or a request log (.jsonl or .jsonl.gz from request_logger.py)")\n    ap.add_argument("--steps", type=int, default=6, help="how many model calls to check")\n    ap.add_argument("--show", action="store_true", help="print the rendered text of the first call")\n    a = ap.parse_args()\n    if a.trace.endswith((".jsonl", ".jsonl.gz")):\n        return check_requests(a.trace)\n    trace = json.loads(Path(a.trace).read_text())\n    tmpl, bos = load_template()\n    tok = Tokenizer.from_file(str(TOK_DIR / "tokenizer.json"))\n    tools = tool_params(DEFAULT_TOOLS)\n    checked = 0\n    for i, st in enumerate(trace["steps"]):\n        if st.get("source") != "agent" or not st.get("metrics"):\n            continue\n        want = st["metrics"]["prompt_tokens"]\n        text = render(tmpl, bos, messages_until(trace, i), tools)\n        got = len(tok.encode(text, add_special_tokens=False).ids)\n        print(f"step {i:3}: vLLM prompt_tokens={want:6}  rendered={got:6}  diff={got - want:+d}")\n        if a.show and checked == 0:\n            print(text[:3000])\n        checked += 1\n        if checked >= a.steps:\n            break\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'}.items():
    (CODE / name).write_text(text)

